    public boolean answer(String permissionId, long expectedRevision, Outcome outcome) {
        return answerDetailed(permissionId, expectedRevision, outcome).accepted();
    }

    public Answer answerDetailed(String permissionId, long expectedRevision, Outcome outcome) {
        Pending value = pending.get(permissionId);
        if (value == null) return new Answer(false, expectedRevision, "already_resolved");
        long currentRevision = value.request.revision();
        if (currentRevision != expectedRevision) {
            return new Answer(false, currentRevision, "revision_mismatch");
        }
        if (!clock.instant().isBefore(value.request.expiresAt())) {
            pending.remove(permissionId, value);
            value.result.complete(new Decision(permissionId, expectedRevision, expectedRevision + 1,
                    Outcome.DENY, clock.instant()));
            return new Answer(false, expectedRevision + 1, "expired");
        }
        boolean accepted = value.result.complete(new Decision(
                permissionId, expectedRevision, expectedRevision + 1, outcome, clock.instant()));
        return new Answer(accepted, expectedRevision + (accepted ? 1 : 0),
                accepted ? "accepted" : "already_resolved");
    }

    public record Answer(boolean accepted, long currentRevision, String reason) {}
    private record Pending(Request request, CompletableFuture<Decision> result) {}
